package dev.pocketllama.photo;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.*;
import org.json.*;

/** OOXML inline strings: recognized values cannot become executable spreadsheet formulas. */
public final class ScanXlsx {
    public static String xml(String s){StringBuilder b=new StringBuilder();s.codePoints().filter(c->c==9||c==10||c==13||c>=32&&c<=0xD7FF||c>=0xE000&&c<=0xFFFD||c>=0x10000&&c<=0x10FFFF).forEach(c->{switch(c){case '&':b.append("&amp;");break;case '<':b.append("&lt;");break;case '>':b.append("&gt;");break;case '"':b.append("&quot;");break;case '\'':b.append("&apos;");break;default:b.appendCodePoint(c);}});return b.toString();}
    private static String column(int n){StringBuilder s=new StringBuilder();for(n++;n>0;n=(n-1)/26)s.insert(0,(char)('A'+(n-1)%26));return s.toString();}
    private static void entry(ZipOutputStream z,String name,String text)throws IOException {z.putNextEntry(new ZipEntry(name));z.write(text.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
    public static void write(OutputStream out,List<JSONObject> tables)throws Exception {
        if(tables.isEmpty())throw new IOException("Нет распознанных таблиц. Запустите Surya для документа");if(tables.size()>200)throw new IOException("Экспортируйте не больше 200 таблиц за раз");
        try(ZipOutputStream z=new ZipOutputStream(out)){StringBuilder types=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>");StringBuilder book=new StringBuilder("<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>"),rels=new StringBuilder("<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">");
            for(int i=0;i<tables.size();i++){JSONObject table=tables.get(i);JSONArray cells=table.getJSONArray("cells");TreeMap<Integer,TreeMap<Integer,JSONObject>> rows=new TreeMap<>();for(int j=0;j<cells.length();j++){JSONObject c=cells.getJSONObject(j);rows.computeIfAbsent(c.getInt("row"),k->new TreeMap<>()).put(c.getInt("col"),c);}StringBuilder sheet=new StringBuilder("<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>"),merges=new StringBuilder();int merged=0;
                for(Map.Entry<Integer,TreeMap<Integer,JSONObject>> row:rows.entrySet()){sheet.append("<row r=\"").append(row.getKey()+1).append("\">");for(Map.Entry<Integer,JSONObject> cell:row.getValue().entrySet()){JSONObject c=cell.getValue();String value=c.optString("text");if(value.length()>32767)throw new IOException("В ячейке больше 32767 символов. Выберите JSON");String ref=column(cell.getKey())+(row.getKey()+1);sheet.append("<c r=\"").append(ref).append("\" t=\"inlineStr\"><is><t xml:space=\"preserve\">").append(xml(value)).append("</t></is></c>");if(c.optInt("rowspan",1)>1||c.optInt("colspan",1)>1){merged++;merges.append("<mergeCell ref=\"").append(ref).append(':').append(column(cell.getKey()+c.optInt("colspan",1)-1)).append(row.getKey()+c.optInt("rowspan",1)).append("\"/>");}}sheet.append("</row>");}sheet.append("</sheetData>");if(merged>0)sheet.append("<mergeCells count=\"").append(merged).append("\">").append(merges).append("</mergeCells>");sheet.append("</worksheet>");entry(z,"xl/worksheets/sheet"+(i+1)+".xml",sheet.toString());types.append("<Override PartName=\"/xl/worksheets/sheet").append(i+1).append(".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>");book.append("<sheet name=\"Таблица ").append(i+1).append("\" sheetId=\"").append(i+1).append("\" r:id=\"rId").append(i+1).append("\"/>");rels.append("<Relationship Id=\"rId").append(i+1).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet").append(i+1).append(".xml\"/>");}
            entry(z,"[Content_Types].xml",types.append("</Types>").toString());entry(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");entry(z,"xl/workbook.xml",book.append("</sheets><calcPr calcMode=\"manual\"/></workbook>").toString());entry(z,"xl/_rels/workbook.xml.rels",rels.append("</Relationships>").toString());
        }
    }
}
